use std::path::Path;
use echode_model::{Project,Id,Tick,NoteDraft,AudioRef,NoteGeometry};
fn main(){
 let args:Vec<_>=std::env::args().collect();
 if args[1]=="boundary" {
  let(p,t)=Project::new().add_track("original");
  let(p,n)=p.insert_note(t,NoteDraft{pitch:60,velocity:100,start:Tick::new(0),length:Tick::new(1)}).unwrap();
  let clip=p.tracks()[0].clips[0].id;
  let p=p.resize_clip(t,clip,Tick::new(0),Tick::new(2)).unwrap();
  let(p,other)=p.add_track("linked");
  let p=p.link_clip(clip,other,Tick::new(i64::MAX-3),Id::from_raw(999)).unwrap();
  println!("before={:?}",p.check_invariants());
  let edit=p.edit_note(t,clip,n,NoteGeometry{pitch:60,start:Tick::new(0),length:Tick::new(8)});
  println!("edit_ok={} invariants={:?}",edit.is_ok(),edit.as_ref().map(|p|p.check_invariants()));
  let insert=p.insert_note(t,NoteDraft{pitch:61,velocity:100,start:Tick::new(1),length:Tick::new(8)});
  println!("insert_ok={} invariants={:?}",insert.is_ok(),insert.as_ref().map(|(p,_)|p.check_invariants()));
 } else if args[1]=="fallback" {
  let package=Path::new("/private/tmp/echode-reaudit-20261014/fallback.echode");
  echode_history::write_package(package,&Project::new()).unwrap();
  let(p,_)=Project::new().add_track("parent");
  let save=echode_history::Autosave::create(package).unwrap();
  let parent=save.save(std::sync::Arc::new(p.clone()),1).unwrap().wait().unwrap();
  let(p,_)=p.add_track("tip");
  let tip=save.save(std::sync::Arc::new(p),2).unwrap().wait().unwrap();drop(save);
  let object=std::process::Command::new("git").arg("-C").arg(package).args(["rev-parse",&format!("{tip}:project.json")]).output().unwrap();
  assert!(object.status.success());let hash=String::from_utf8(object.stdout).unwrap();let hash=hash.trim();
  std::fs::remove_file(package.join(".git/objects").join(&hash[..2]).join(&hash[2..])).unwrap();
  let host=echode_history::DocumentHost::open(package).unwrap();
  println!("parent={parent} tip={tip} recovered_tracks={} label={:?}",host.snapshot().tracks().len(),host.recovered_label());
 } else if args[1]=="wave" {
  let package=Path::new("/private/tmp/echode-reaudit-20261014/wave.echode");
  let(mut bytes,frames)=(Vec::new(),96000u64);
  bytes.extend_from_slice(b"ECHDPCM1");bytes.extend_from_slice(&48000u32.to_le_bytes());bytes.extend_from_slice(&1u16.to_le_bytes());bytes.extend_from_slice(&0u16.to_le_bytes());bytes.extend_from_slice(&frames.to_le_bytes());
  for i in 0..frames {bytes.extend_from_slice(&(if i<frames/2{0.25f32}else{0.75}).to_le_bytes());}
  let(p,t)=Project::new().add_track("wave");echode_history::write_package(package,&p).unwrap();
  let hash=echode_history::write_object(package,&bytes).unwrap();
  let clip=Id::from_raw(901);
  let p=p.place_audio(t,clip,Id::from_raw(902),Tick::new(0),AudioRef::try_new(hash,48000,1,frames).unwrap()).unwrap();
  let length=p.tracks()[0].clips[0].length.get();
  let p=p.resize_clip(t,clip,Tick::new(length/2),Tick::new(length/2)).unwrap();
  println!("trimmed_start={} offset={} invariants={:?}",length/2,p.tracks()[0].clips[0].offset.get(),p.check_invariants());
  let waves=echode_history::Waveforms::load(package,&p,None);
  let mut columns=vec![echode_history::PeakColumn{min:0.0,max:0.0};8];
  println!("written={} expected_all=0.75 columns={:?}",waves.fill(&p,clip,length/2,length,&mut columns),columns);
 } else if args[1]=="wav" {
  let package=Path::new("/private/tmp/echode-reaudit-20261014/fail.echode");
  let cache=Path::new("/private/tmp/echode-reaudit-20261014/cache.jsonl");
  unsafe{std::env::set_var("ECHODE_PLUGIN_CACHE",cache);std::env::set_var("ECHODE_PLUGIN_HOST",&args[2]);}
  let(p,t)=Project::new().add_track("fail");
  let p=p.add_clap_device(t,Id::from_raw(903),"dev.audit.mono").unwrap();
  echode_history::write_package(package,&p).unwrap();
  let plugin=echode_plugin_host::ScannedPlugin{id:"dev.audit.mono".into(),name:"Probe".into(),vendor:"Audit".into(),version:"1".into(),features:vec!["instrument".into()],url:String::new()};
  let entry=echode_plugin_host::cache_entry(Path::new(&args[3]),vec![plugin]);
  echode_plugin_host::store_scan_cache(cache,&[entry]).unwrap();
  let output=package.join("existing.wav");
  std::fs::write(&output,b"previous successful user export").unwrap();
  let result=echode_cli::render_to_wav(package,&output,48000,Some(4096));
  println!("render_result={result:?} original_exists={} remaining={:?}",output.exists(),std::fs::read(&output));
 }
}

