fn note(p:Project,t:Id,start:i64)->Project{p.insert_note(t,NoteDraft{pitch:60,velocity:100,start:Tick::new(start),length:Tick::quarters(2).unwrap()}).unwrap().0}
fn main(){
 let host=Path::new("/Users/someone/Echode/target/debug/echode-plugin-host");
 let route=PluginRoute{clap_id:"dev.audit.mono".into(),path:"/private/tmp/echode-reaudit-20261014/declared_note_plugin.dylib".into(),instrument:true,fault:None,state:None};
 for (future,rapid) in [(false,false),(true,false),(false,true)]{
